#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
vector<long long>a,tmp;
void ms(int lo,int hi){
if(hi-lo<=1)return;
int mid=(lo+hi)/2;
ms(lo,mid);ms(mid,hi);
int i=lo,j=mid,k=lo;
while(i<mid&&j<hi){if(a[i]<=a[j])tmp[k++]=a[i++];else tmp[k++]=a[j++];}
while(i<mid)tmp[k++]=a[i++];
while(j<hi)tmp[k++]=a[j++];
for(int t=lo;t<hi;++t)a[t]=tmp[t];}
int main(){int n;scanf("%d",&n);a.resize(n);tmp.resize(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
ms(0,n);
for(int i=0;i<n;++i){if(i)printf(" ");printf("%lld",a[i]);}
printf("\n");return 0;}

